  run(async () => { await api('/api/session', 'DELETE', {}); token = ''; session = null; $('session-key').value = ''; $('turns').replaceChildren(); $('experiment').replaceChildren(); $('conversation').hidden = true; $('onboarding').hidden = false; $('intake').reset(); });
